<?php
if (!defined('PORTAL_VIEW_ROUTER')) { http_response_code(403); exit; }
title('Quản lý bầu cử');panel('Tạo bầu cử');form_open('save_election');inputf('Tên cuộc bầu cử','title','','text','required');inputf('Mô tả','description');inputf('Bắt đầu','starts_at','','datetime-local','required');inputf('Kết thúc','ends_at','','datetime-local','required');inputf('Số người tối đa mỗi phiếu','seats','1','number','min="1" max="20"');submitf('Tạo');echo '</section>';
 foreach(rows('SELECT * FROM elections ORDER BY id DESC') as $el){panel($el['title']);echo '<p>'.e($el['starts_at']).' – '.e($el['ends_at']).'</p>';form_open('add_candidate');echo '<input type="hidden" name="election_id" value="'.(int)$el['id'].'">';inputf('MSSV ứng viên','student_id','','text','required');submitf('Thêm ứng viên');echo '<div class="line"><b>Ứng viên</b><span></span></div>';foreach(rows('SELECT u.full_name FROM candidates c JOIN users u ON u.id=c.user_id WHERE c.election_id=?',[$el['id']]) as $c)echo '<p>'.e($c['full_name']).'</p>';
 if(time()>strtotime($el['ends_at'])){echo '<h3>Kết quả sau khi kết thúc</h3>';foreach(rows('SELECT u.full_name,COUNT(b.id) AS votes FROM candidates c JOIN users u ON u.id=c.user_id LEFT JOIN ballots b ON b.candidate_id=c.id WHERE c.election_id=? GROUP BY c.id,u.full_name ORDER BY votes DESC',[$el['id']]) as $v)echo '<div class="line"><span>'.e($v['full_name']).'</span><b>'.e($v['votes']).' phiếu</b></div>';}else echo '<p class="muted">Kết quả chỉ hiện sau khi đóng bầu cử.</p>';echo '</section>';}
